  assert.equal(result[0].rate, 19);
  assert.equal(result[0].base, 90);
  assert.equal(result[0].vat, 17);
});

test('vatSummary - multiple invoices aggregated', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 19 }],
    },
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 200, discountPercent: 0, vatRate: 19 }],
    },
  ];

